<?php require 'config.php'; require_login();$activePage="tasks";$me=user();$vol=$pdo->prepare('SELECT id,status FROM volunteers WHERE user_id=?');$vol->execute([$me['id']]);$vp=$vol->fetch();$isVolunteer=(bool)$vp;$requests=[];if($isVolunteer&&$vp['status']==='Active'){$q=$pdo->query("SELECT r.*,u.first_name,u.last_name FROM requests r JOIN users u ON u.id=r.user_id WHERE r.status='Pending' ORDER BY r.created_at DESC");$requests=$q->fetchAll();}$mine=$pdo->prepare("SELECT r.*,CONCAT(COALESCE(v.first_name,''),' ',COALESCE(v.last_name,'')) volunteer_name FROM requests r LEFT JOIN users v ON v.id=r.volunteer_id WHERE r.user_id=? ORDER BY r.created_at DESC");$mine->execute([$me['id']]);$myRequests=$mine->fetchAll();$accepted=[];if($isVolunteer){$q=$pdo->prepare("SELECT r.*,u.first_name,u.last_name FROM requests r JOIN users u ON u.id=r.user_id WHERE r.volunteer_id=? ORDER BY r.created_at DESC");$q->execute([$me['id']]);$accepted=$q->fetchAll();} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Volunteer Tasks | Helping Hands</title><link rel="stylesheet" href="common.css"></head><body><?php include 'partials/header.php'; ?><main class="form-page"><div class="container"><div class="section-title reveal"><span class="eyebrow">TASK CENTRE</span><h2>Volunteer tasks & requests</h2><p>See available requests, accept suitable tasks and track work you have completed.</p></div><?php if(!$isVolunteer): ?><div class="panel"><h3>Ready to volunteer?</h3><p>You haven't completed a volunteer application yet. Complete it to unlock the Task Centre.</p><a class="btn primary" href="volunteer.php">Become a volunteer</a></div><?php elseif($vp['status']!=='Active'): ?><div class="panel"><h3>Your volunteer profile is paused</h3><p>Update your volunteer application to reactivate it before accepting tasks.</p><a class="btn primary" href="volunteer.php">Update profile</a></div><?php else: ?><div class="panel"><h3>Available requests</h3><?php if(!$requests): ?><p class="muted">There are no pending requests right now. Check again later.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Help</th><th>Area</th><th>Date</th><th>Requester</th><th>Action</th></tr></thead><tbody><?php foreach($requests as $r): ?><tr><td><?php echo h($r['category']); ?></td><td><?php echo h($r['location']); ?></td><td><?php echo h($r['preferred_date']); ?><br><?php echo h(substr($r['preferred_time'],0,5)); ?></td><td><?php echo h($r['first_name'].' '.$r['last_name']); ?></td><td><form method="post" action="accept_task.php"><input type="hidden" name="csrf" value="<?php echo h(csrf_token()); ?>"><input type="hidden" name="request_id" value="<?php echo (int)$r['id']; ?>"><button class="btn primary small">Accept</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><div class="panel" style="margin-top:18px"><h3>Tasks I accepted</h3><?php if(!$accepted): ?><p class="muted">You have not accepted a task yet.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Help</th><th>Requester</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($accepted as $r): ?><tr><td><?php echo h($r['category']); ?><br><small><?php echo h($r['location']); ?></small></td><td><?php echo h($r['first_name'].' '.$r['last_name']); ?></td><td><span class="badge <?php echo $r['status']==='Completed'?'orange':''; ?>"><?php echo h($r['status']); ?></span></td><td><?php if($r['status']==='Accepted'): ?><form method="post" action="complete_task.php"><input type="hidden" name="csrf" value="<?php echo h(csrf_token()); ?>"><input type="hidden" name="request_id" value="<?php echo (int)$r['id']; ?>"><button class="btn secondary small">Mark completed</button></form><?php else: ?>Done<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php endif; ?><div class="panel" style="margin-top:18px"><h3>My help requests</h3><?php if(!$myRequests): ?><p class="muted">You have not submitted a help request yet.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>When</th><th>Status</th><th>Volunteer</th></tr></thead><tbody><?php foreach($myRequests as $r): ?><tr><td><?php echo h($r['category']); ?><br><small><?php echo h($r['location']); ?></small></td><td><?php echo h($r['preferred_date']); ?><br><?php echo h(substr($r['preferred_time'],0,5)); ?></td><td><span class="badge <?php echo $r['status']==='Completed'?'orange':''; ?>"><?php echo h($r['status']); ?></span></td><td><?php echo trim($r['volunteer_name'])?h(trim($r['volunteer_name'])):'Not assigned'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></main><?php include 'partials/footer.php'; ?></body></html>
